<template><div class="space-y-6"><CPageHeader title="Historial de cambios" description="Registro de modificaciones, responsables y valores anteriores. Las contraseñas se excluyen del historial." /><p v-if="error" role="alert" class="operation-error">{{ error }}</p><CCard><form class="operation-form mb-6" @submit.prevent="page=1;load()"><label>Sección <select v-model="filters.table"><option value="">Todas</option><option v-for="(label,key) in tables" :key="key" :value="key">{{ label }}</option></select></label><label>Acción <select v-model="filters.action"><option value="">Todas</option><option value="INSERT">Creación</option><option value="UPDATE">Modificación</option><option value="DELETE">Eliminación</option></select></label><label>Responsable <select v-model="filters.user_id"><option value="">Todos</option><option v-for="s in staff" :key="s.id" :value="s.id">{{ s.name }}</option></select></label><label>Desde <input v-model="filters.start" type="date"></label><label>Hasta <input v-model="filters.end" type="date"></label><label>ID del registro <input v-model="filters.record_id" type="number" min="1"></label><CButton :loading="busy" type="submit">Filtrar</CButton></form><div class="operation-scroll"><table class="operation-table"><thead><tr><th>Fecha</th><th>Responsable</th><th>Sección / registro</th><th>Acción</th><th>Cambios</th></tr></thead><tbody><tr v-for="a in entries" :key="a.id"><td>{{ dateTime(a.created_at) }}</td><td>{{ a.user_name || 'Sistema / migración' }}</td><td>{{ tables[a.table_name] || a.table_name }} #{{ a.record_id }}</td><td>{{ actions[a.action] || a.action }}</td><td><details><summary>Ver valores</summary><div v-for="key in changed(a)" :key="key" class="audit-change"><strong>{{ key }}</strong><div>Antes: {{ display(a.old_value?.[key]) }}</div><div>Después: {{ display(a.new_value?.[key]) }}</div></div></details></td></tr></tbody></table></div><p v-if="!entries.length">No hay cambios con estos filtros.</p><div class="operation-pager"><CButton variant="secondary" :disabled="page===1||busy" @click="page--;load()">Anterior</CButton><span>{{ page }} / {{ Math.max(1,pages) }}</span><CButton variant="secondary" :disabled="page>=pages||busy" @click="page++;load()">Siguiente</CButton></div></CCard></div></template>
<script setup lang="ts">
import type { AuditEntry, StaffOption } from '~/types/operations'
definePageMeta({middleware:['auth','manager']})
const {get,list,run,error,busy}=useOperations(),{dateTime}=useHotelSettings()
const entries=ref<AuditEntry[]>([]),staff=ref<StaffOption[]>([]),page=ref(1),pages=ref(1)
const filters=reactive({table:'',action:'',user_id:'',record_id:'',start:'',end:''})
const tables:Record<string,string>={reservation:'Reservas',payment:'Pagos',room:'Habitaciones',client:'Huéspedes',user:'Equipo',hotel_settings:'Configuración',housekeeping_task:'Tareas',cash_shift:'Caja',room_type:'Tipos de habitación',check_in_log:'Entradas y salidas'}
const actions:Record<string,string>={INSERT:'Creación',UPDATE:'Modificación',DELETE:'Eliminación'}
const changed=(a:AuditEntry)=>Array.from(new Set([...Object.keys(a.old_value||{}),...Object.keys(a.new_value||{})])).filter(k=>JSON.stringify(a.old_value?.[k])!==JSON.stringify(a.new_value?.[k]))
const display=(v:unknown)=>v===null||v===undefined?'—':typeof v==='object'?JSON.stringify(v):String(v)
const load=()=>run(async()=>{const q:Record<string,string|number|undefined>={page:page.value};for(const [k,v] of Object.entries(filters))q[k]=v||undefined;const r=await list<AuditEntry>('audit',q);entries.value=r.data||[];pages.value=r.pagination.totalPages})
onMounted(async()=>{await load();await run(async()=>{staff.value=(await get<StaffOption[]>('task-assignees')).data||[]})})
</script>
<style scoped>.audit-change{padding:8px 0;max-width:420px;overflow-wrap:anywhere}summary{cursor:pointer;color:#535ed6}</style>
